def recurse(f): def r: ., (f | select(. != null) | r); r;
def while(cond; update):

  def _while:

    if cond then ., (update | _while) else empty end;

  _while;
def repeat(exp):

  def _repeat:

    exp, _repeat;

  _repeat;
